    newVault: TAccountMetas[6];
    vaultTokenAccount?: TAccountMetas[7] | undefined;
    newVaultTokenAccount?: TAccountMetas[8] | undefined;
    mint?: TAccountMetas[9] | undefined;
    tokenProgram: TAccountMetas[10];
